python3 -c "
import re
with open('/home/user/JSS-2026-Example/software/mcfm/src/Mods/ppwp2j_mod.f90') as f:
    content = f.read()
start = content.index('reshape((/') + len('reshape((/')
end = content.index('/) &\n    , (/ 9,9,9,9 /))')
data_str = content[start:end]
nums = re.findall(r'-?\d+', data_str)
assert len(nums) == 6561, f'Expected 6561, got {len(nums)}'
lines = []
for i in range(0, len(nums), 27):
    chunk = nums[i:i+27]
    if i + 27 >= len(nums):
        lines.append('    ' + ', '.join(chunk))
    else:
        lines.append('    ' + ', '.join(chunk) + ',')
body = '\n'.join(lines)

cpp = '''#include <ppwp2j_mod.hpp>

// pp(-4:4,-4:4,-4:4,-4:4) stored in Fortran column-major order.
// Flat index: (i+4) + 9*(j+4) + 81*(k+4) + 729*(l+4)
// where i,j,k,l each range from -4 to 4.
namespace ppwp2j_mod {
    int pp[6561] = {
''' + body + '''
    };
}

extern \"C\" {
    int* ppwp2j_mod_pp() { // @coverage-probe
        return ppwp2j_mod::pp;
    }
}
'''
with open('/home/user/JSS-2026-Example/software/mcfm/src/Mods/ppwp2j_mod.cpp', 'w') as f:
    f.write(cpp)
print('Done. File written.')
"
